          <br />
          <span className="bg-gradient-to-r from-purple-300 via-pink-300 to-purple-400 bg-clip-text text-transparent">
            Travel Planner
          </span>
        </motion.h1>

        <motion.p
          initial={{ opacity: 0, y: 30 }}
